class Ticket {
  constructor(id, vehicleNumber, slotId, entryTime) {
    this.id = id;
    this.vehicleNumber = vehicleNumber;
    this.slotId = slotId;
    this.entryTime = entryTime;
  }
}

class ParkingLot {
  constructor(totalSlots, ratePerHour) {
    this.ratePerHour = ratePerHour;
    this.freeSlots = [];
    for (let i = 1; i <= totalSlots; i++) this.freeSlots.push(i);
    this.tickets = new Map();
    this.nextTicketId = 1;
  }

  park(vehicleNumber) {
    if (this.freeSlots.length === 0) {
      throw new Error("Parking lot is full");
    }
    const slotId = this.freeSlots.shift();
    const ticket = new Ticket(this.nextTicketId++, vehicleNumber, slotId, Date.now());
    this.tickets.set(ticket.id, ticket);
    return ticket;
  }

  unpark(ticketId, exitTime = Date.now()) {
    const ticket = this.tickets.get(ticketId);
    if (!ticket) throw new Error("Invalid ticket");
    const hours = Math.max(1, Math.ceil((exitTime - ticket.entryTime) / 3600000));
    const fee = hours * this.ratePerHour;
    this.freeSlots.push(ticket.slotId);
    this.tickets.delete(ticketId);
    return { ticketId, hours, fee };
  }
}

const lot = new ParkingLot(2, 20);
const t1 = lot.park("KA-01-HH-1234");
lot.park("KA-02-MM-5678");
console.log("Issued ticket", t1.id, "for slot", t1.slotId);
console.log("Receipt:", lot.unpark(t1.id, t1.entryTime + 2 * 3600000));

