import java.util.*;

class Ticket {
    int id;
    String vehicleNumber;
    int slotId;
    long entryTime;

    Ticket(int id, String vehicleNumber, int slotId, long entryTime) {
        this.id = id;
        this.vehicleNumber = vehicleNumber;
        this.slotId = slotId;
        this.entryTime = entryTime;
    }
}

class ParkingLot {
    private Deque<Integer> freeSlots = new ArrayDeque<>();
    private Map<Integer, Ticket> tickets = new HashMap<>();
    private int nextTicketId = 1;
    private double ratePerHour;

    ParkingLot(int totalSlots, double ratePerHour) {
        this.ratePerHour = ratePerHour;
        for (int i = 1; i <= totalSlots; i++) freeSlots.add(i);
    }

    Ticket park(String vehicleNumber) {
        if (freeSlots.isEmpty()) throw new RuntimeException("Parking lot is full");
        int slotId = freeSlots.poll();
        Ticket ticket = new Ticket(nextTicketId++, vehicleNumber, slotId, System.currentTimeMillis());
        tickets.put(ticket.id, ticket);
        return ticket;
    }

    double unpark(int ticketId, long exitTime) {
        Ticket ticket = tickets.remove(ticketId);
        if (ticket == null) throw new RuntimeException("Invalid ticket");
        long hours = Math.max(1, (exitTime - ticket.entryTime) / 3600000 + 1);
        double fee = hours * ratePerHour;
        freeSlots.add(ticket.slotId);
        return fee;
    }
}

public class Main {
    public static void main(String[] args) {
        ParkingLot lot = new ParkingLot(2, 20);
        Ticket t1 = lot.park("KA-01-HH-1234");
        lot.park("KA-02-MM-5678");
        System.out.println("Issued ticket " + t1.id + " for slot " + t1.slotId);
        double fee = lot.unpark(t1.id, t1.entryTime + 2 * 3600000);
        System.out.println("Fee due: " + fee);
    }
}

