#include <bits/stdc++.h>
#include <chrono>
using namespace std;

class Ticket {
public:
    int id;
    string vehicleNumber;
    int slotId;
    long long entryTime;

    Ticket(int id, string vehicleNumber, int slotId, long long entryTime)
        : id(id), vehicleNumber(vehicleNumber), slotId(slotId), entryTime(entryTime) {}
};

class ParkingLot {
    deque<int> freeSlots;
    map<int, Ticket> tickets;
    int nextTicketId = 1;
    double ratePerHour;

public:
    ParkingLot(int totalSlots, double ratePerHour) : ratePerHour(ratePerHour) {
        for (int i = 1; i <= totalSlots; i++) freeSlots.push_back(i);
    }

    Ticket park(const string& vehicleNumber) {
        if (freeSlots.empty()) throw runtime_error("Parking lot is full");
        int slotId = freeSlots.front();
        freeSlots.pop_front();
        long long now = chrono::duration_cast<chrono::milliseconds>(
            chrono::system_clock::now().time_since_epoch()).count();
        Ticket ticket(nextTicketId++, vehicleNumber, slotId, now);
        tickets.insert({ticket.id, ticket});
        return ticket;
    }

    double unpark(int ticketId, long long exitTime) {
        auto it = tickets.find(ticketId);
        if (it == tickets.end()) throw runtime_error("Invalid ticket");
        Ticket ticket = it->second;
        tickets.erase(it);
        long long hours = max(1LL, (exitTime - ticket.entryTime) / 3600000 + 1);
        double fee = hours * ratePerHour;
        freeSlots.push_back(ticket.slotId);
        return fee;
    }
};

int main() {
    ParkingLot lot(2, 20);
    Ticket t1 = lot.park("KA-01-HH-1234");
    lot.park("KA-02-MM-5678");
    cout << "Issued ticket " << t1.id << " for slot " << t1.slotId << endl;
    double fee = lot.unpark(t1.id, t1.entryTime + 2 * 3600000);
    cout << "Fee due: " << fee << endl;
    return 0;
}
